CREATE TYPE "series_status" AS ENUM (
  'ANNOUNCED',
  'ON_GOING',
  'FINISHED',
  'ABANDONED'
);

CREATE TYPE "user_has_book_status" AS ENUM (
  'WISHLISTED',
  'OWNED'
);

CREATE TABLE "image" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar UNIQUE NOT NULL,
  "url" varchar NOT NULL,
  "created_at" timestamp,
  "updated_at" timestamp
);

CREATE TABLE "editor" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar UNIQUE NOT NULL,
  "created_at" timestamp,
  "updated_at" timestamp
);

CREATE TABLE "author_type" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar UNIQUE NOT NULL,
  "created_at" timestamp,
  "updated_at" timestamp
);

CREATE TABLE "author" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "firstname" varchar NOT NULL,
  "lastname" varchar NOT NULL,
  "birthday" date NOT NULL,
  "avatar_id" integer,
  "created_at" timestamp,
  "updated_at" timestamp
);

ALTER TABLE "author" ADD FOREIGN KEY ("avatar_id") REFERENCES "image" ("id");
CREATE UNIQUE INDEX ON "author" ("firstname", "lastname");


CREATE TABLE "category" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar UNIQUE NOT NULL,
  "created_at" timestamp,
  "updated_at" timestamp
);

CREATE TABLE "series" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar UNIQUE NOT NULL,
  "status" series_status NOT NULL,
  "category_id" integer NOT NULL,
  "created_at" timestamp,
  "updated_at" timestamp
);

ALTER TABLE "series" ADD FOREIGN KEY ("category_id") REFERENCES "category" ("id");
CREATE INDEX "idx_series_category_id" ON "series" ("category_id");

CREATE TABLE "theme" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar UNIQUE NOT NULL,
  "created_at" timestamp,
  "updated_at" timestamp
);

CREATE TABLE "series_has_theme" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "series_id" integer NOT NULL,
  "theme_id" integer NOT NULL,
  "created_at" timestamp,
  "updated_at" timestamp,
  UNIQUE ("series_id", "theme_id")
);

ALTER TABLE "series_has_theme" ADD FOREIGN KEY ("series_id") REFERENCES "series" ("id");
ALTER TABLE "series_has_theme" ADD FOREIGN KEY ("theme_id") REFERENCES "theme" ("id");
CREATE INDEX "idx_series_has_theme_series_id" ON "series_has_theme" ("series_id");
CREATE INDEX "idx_series_has_theme_theme_id" ON "series_has_theme" ("theme_id");
CREATE UNIQUE INDEX ON "series_has_theme" ("series_id", "theme_id");

CREATE TABLE "book" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar NOT NULL,
  "page_count" integer NOT NULL,
  "volume" integer,
  "weight" integer,
  "price" integer,
  "series_id" integer NOT NULL,
  "editor_id" integer NOT NULL,
  "release_date" timestamp NOT NULL,
  "created_at" timestamp,
  "updated_at" timestamp
);

ALTER TABLE "book" ADD FOREIGN KEY ("series_id") REFERENCES "series" ("id");
ALTER TABLE "book" ADD FOREIGN KEY ("editor_id") REFERENCES "editor" ("id");
CREATE INDEX "idx_book_series_id" ON "book" ("series_id");
CREATE INDEX "idx_book_editor_id" ON "book" ("editor_id");
CREATE INDEX "idx_book_release_date" ON "book" ("release_date");
CREATE INDEX "idx_book_price" ON "book" ("price");

CREATE TABLE "book_has_author" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "book_id" integer NOT NULL,
  "author_id" integer NOT NULL,
  "author_type_id" integer NOT NULL,
  "created_at" timestamp,
  "updated_at" timestamp
);

ALTER TABLE "book_has_author" ADD FOREIGN KEY ("book_id") REFERENCES "book" ("id");
ALTER TABLE "book_has_author" ADD FOREIGN KEY ("author_id") REFERENCES "author" ("id");
ALTER TABLE "book_has_author" ADD FOREIGN KEY ("author_type_id") REFERENCES "author_type" ("id");
CREATE INDEX "idx_book_has_author_book_id" ON "book_has_author" ("book_id");
CREATE INDEX "idx_book_has_author_author_id" ON "book_has_author" ("author_id");
CREATE UNIQUE INDEX ON "book_has_author" ("book_id", "author_id", "author_type_id");

CREATE TABLE "book_has_image" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "book_id" integer NOT NULL,
  "image_id" integer NOT NULL,
  "created_at" timestamp,
  "updated_at" timestamp
);

ALTER TABLE "book_has_image" ADD FOREIGN KEY ("book_id") REFERENCES "book" ("id");
ALTER TABLE "book_has_image" ADD FOREIGN KEY ("image_id") REFERENCES "image" ("id");
CREATE INDEX "idx_book_has_image_book_id" ON "book_has_image" ("book_id");
CREATE INDEX "idx_book_has_image_image_id" ON "book_has_image" ("image_id");
CREATE UNIQUE INDEX ON "book_has_image" ("book_id", "image_id");

CREATE TABLE "user" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "username" varchar UNIQUE NOT NULL,
  "firstname" varchar,
  "lastname" varchar,
  "email" varchar UNIQUE NOT NULL,
  "password" varchar NOT NULL,
  "avatar_id" integer,
  "created_at" timestamp,
  "updated_at" timestamp
);

ALTER TABLE "user" ADD FOREIGN KEY ("avatar_id") REFERENCES "image" ("id");

