  "updated_at" timestamp
);

ALTER TABLE "user_follows_author" ADD FOREIGN KEY ("user_id") REFERENCES "user" ("id");
ALTER TABLE "user_follows_author" ADD FOREIGN KEY ("author_id") REFERENCES "author" ("id");
CREATE INDEX "idx_user_follows_author_user_id" ON "user_follows_author" ("user_id");
CREATE INDEX "idx_user_follows_author_author_id" ON "user_follows_author" ("author_id");
CREATE INDEX "idx_user_follows_author_created_at" ON "user_follows_author" ("created_at");
CREATE UNIQUE INDEX ON "user_follows_author" ("user_id", "author_id");

CREATE TABLE "user_follows_editor" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" integer NOT NULL,
  "editor_id" integer NOT NULL,
  "created_at" timestamp,
  "updated_at" timestamp
);

ALTER TABLE "user_follows_editor" ADD FOREIGN KEY ("user_id") REFERENCES "user" ("id");
ALTER TABLE "user_follows_editor" ADD FOREIGN KEY ("editor_id") REFERENCES "editor" ("id");
CREATE INDEX "idx_user_follows_editor_user_id" ON "user_follows_editor" ("user_id");
CREATE INDEX "idx_user_follows_editor_editor_id" ON "user_follows_editor" ("editor_id");
CREATE INDEX "idx_user_follows_editor_created_at" ON "user_follows_editor" ("created_at");
