CREATE TABLE "user_has_book" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" integer NOT NULL,
  "book_id" integer NOT NULL,
  "status" user_has_book_status NOT NULL,
  "created_at" timestamp,
  "updated_at" timestamp
);

ALTER TABLE "user_has_book" ADD FOREIGN KEY ("user_id") REFERENCES "user" ("id");
ALTER TABLE "user_has_book" ADD FOREIGN KEY ("book_id") REFERENCES "book" ("id");
CREATE INDEX "idx_user_has_book_user_id" ON "user_has_book" ("user_id");
CREATE INDEX "idx_user_has_book_book_id" ON "user_has_book" ("book_id");
CREATE INDEX "idx_user_has_book_created_at" ON "user_has_book" ("created_at");
