  "value" varchar,
  "created_at" timestamp,
  "updated_at" timestamp
);

ALTER TABLE "user_has_book_has_additional_data" ADD FOREIGN KEY ("user_has_book_id") REFERENCES "user_has_book" ("id");
CREATE INDEX "idx_user_has_book_has_additional_data_user_has_book_id" ON "user_has_book_has_additional_data" ("user_has_book_id");
