ALTER TABLE "user_reads_book" ADD FOREIGN KEY ("user_id") REFERENCES "user" ("id");
ALTER TABLE "user_reads_book" ADD FOREIGN KEY ("book_id") REFERENCES "book" ("id");
CREATE INDEX "idx_user_reads_book_book_id" ON "user_reads_book" ("book_id");
